cat > /workspace/src/entr.c <<'CEOF'
#define _POSIX_C_SOURCE 200809L
#define _DEFAULT_SOURCE 1

#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <sys/inotify.h>
#include <dirent.h>
#include <err.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <poll.h>
#include <pwd.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/* kqueue-style note flags used in trace output */
#define NOTE_DELETE 0x01u
#define NOTE_WRITE  0x02u
#define NOTE_EXTEND 0x04u
#define NOTE_ATTRIB 0x08u
#define NOTE_LINK   0x10u
#define NOTE_RENAME 0x20u
#define NOTE_REVOKE 0x40u

static const char *release_str = "5.7";

/* options */
static int opt_a, opt_c_count, opt_d_count, opt_n, opt_p, opt_r, opt_s;
static int opt_x_count, opt_z;
static int restart_signal = SIGTERM;
static int follow_symlink;
static int inotify_workaround;

static char **utility_args;
static int utility_argc;
static const char *shell_command;

/* watched files */
typedef struct {
    char *name;
    mode_t mode;
    int is_dir;
    int is_parent;
    int symlink_profile;   /* initially a symlink and ENTR_FOLLOW_SYMLINK unset */
    int currently_symlink;
    int dir_count;
    int wd;
    int watch_is_dir;
} WatchFile;

static WatchFile *files;
static size_t files_len, files_cap;
static WatchFile *trigger_file;

/* status (-x) process */
static char *status_script_path;
static int status_script_need_create;
static pid_t status_pid;
static int status_fd = -1;
static int status_dead;

/* terminal */
static int tty_fd = -1;
static struct termios tty_orig, tty_new;
static int tty_active;              /* modified termios is entr's state */
static void restore_tty_now(void)
{
    if (tty_active && tty_fd >= 0) {
        tcsetattr(tty_fd, TCSANOW, &tty_orig);
    }
}
static void restore_tty_atexit(void)
{
    restore_tty_now();
}

/* signals */
static volatile sig_atomic_t seen_int, seen_hup, seen_term, seen_chld;
static int sig_pipe[2] = { -1, -1 };

static void signal_handler(int sig)
{
    int saved = errno;
    if (sig == SIGINT) seen_int = 1;
    else if (sig == SIGHUP) seen_hup = 1;
    else if (sig == SIGTERM) seen_term = 1;
    else if (sig == SIGCHLD) seen_chld = 1;
    if (sig_pipe[1] >= 0) {
        unsigned char b = (unsigned char)sig;
        ssize_t ignored = write(sig_pipe[1], &b, 1);
        (void)ignored;
    }
    errno = saved;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);
    sigaction(SIGCHLD, &sa, NULL);
    if (opt_r)
        sigaction(SIGTERM, &sa, NULL);
}

static int64_t now_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

/* status child: returns 1 if it has terminated (message printed once) */
static int check_status_dead(void)
{
    if (!opt_x_count || status_pid <= 0 || status_dead)
        return status_dead;
    int st;
    pid_t r;
    do {
        r = waitpid(status_pid, &st, WNOHANG);
    } while (r < 0 && errno == EINTR && 0);
    if (r == status_pid || (r < 0 && errno == ECHILD)) {
        status_dead = 1;
        warnx("status process terminated");
        return 1;
    }
    return 0;
}

static void exit_by_term_signal(void)
{
    restore_tty_now();
    tty_active = 0;
    signal(SIGTERM, SIG_DFL);
    raise(SIGTERM);
    _exit(128 + SIGTERM);
}

/* If a terminating condition is pending and no utility child is being
 * waited on, act on it.  Returns only if nothing to do. */
static void check_immediate_exits(void)
{
    if (seen_int || seen_hup)
        exit(0);
    if (opt_r && seen_term)
        exit_by_term_signal();
    if (check_status_dead())
        exit(0);
}

/* interruptible sleep; returns 0 normally, -1 if interrupted by a signal */
static int sleep_ms_interruptible(int ms)
{
    struct timespec req;
    req.tv_sec = ms / 1000;
    req.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&req, &req) < 0) {
        if (errno != EINTR)
            return 0;
        if (seen_int || seen_hup || (opt_r && seen_term))
            return -1;
        if (opt_x_count && seen_chld && check_status_dead())
            return -1;
        seen_chld = 0;
    }
    return 0;
}

/* ---------- small utilities ---------- */

static void *xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (!p) err(1, "malloc");
    return p;
}
static void *xrealloc(void *p, size_t n)
{
    void *q = realloc(p, n ? n : 1);
    if (!q) err(1, "realloc");
    return q;
}
static char *xstrdup(const char *s)
{
    char *p = strdup(s ? s : "");
    if (!p) err(1, "strdup");
    return p;
}

/* basename as used in status lines: strip trailing slashes first */
static char *status_basename(const char *path)
{
    if (!path || !*path)
        return xstrdup("");
    char *copy = xstrdup(path);
    size_t len = strlen(copy);
    while (len > 1 && copy[len - 1] == '/')
        copy[--len] = '\0';
    char *slash = strrchr(copy, '/');
    char *res = xstrdup(slash ? slash + 1 : copy);
    free(copy);
    return res;
}

/* dirname-like extraction used for -d parent directories */
static char *parent_dirname(const char *path)
{
    if (!path || !*path)
        return xstrdup(".");
    char *copy = xstrdup(path);
    size_t len = strlen(copy);
    /* remove trailing slashes (but keep a lone root) */
    while (len > 1 && copy[len - 1] == '/')
        copy[--len] = '\0';
    char *slash = strrchr(copy, '/');
    if (!slash) {
        free(copy);
        return xstrdup(".");
    }
    if (slash == copy) {
        free(copy);
        return xstrdup("/");
    }
    *slash = '\0';
    len = strlen(copy);
    while (len > 1 && copy[len - 1] == '/')
        copy[--len] = '\0';
    if (copy[0] == '\0') {
        free(copy);
        return xstrdup("/");
    }
    return copy;
}

static int count_dir_entries(const char *path)
{
    DIR *d = opendir(path);
    if (!d)
        errx(1, "unable to open directory: '%s'", path);
    int count = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        const char *nm = de->d_name;
        if (opt_d_count < 2) {
            if (nm[0] == '.')
                continue;
        } else {
            if (strcmp(nm, ".") == 0 || strcmp(nm, "..") == 0)
                continue;
        }
        count++;
    }
    closedir(d);
    return count;
}

static int stat_for_mode(const char *path, struct stat *sb)
{
    if (follow_symlink)
        return stat(path, sb);
    return lstat(path, sb);
}

static void files_append(WatchFile wf)
{
    if (files_len == files_cap) {
        files_cap = files_cap ? files_cap * 2 : 16;
        files = xrealloc(files, files_cap * sizeof(*files));
    }
    files[files_len++] = wf;
}

/* ---------- inotify registration ---------- */

#define FILE_MASK (IN_CLOSE_WRITE | IN_ATTRIB | IN_DELETE_SELF | IN_MOVE_SELF)
#define FILE_MASK_WORKAROUND (FILE_MASK | IN_MODIFY)
#define DIR_MASK (IN_CLOSE_WRITE | IN_ATTRIB | IN_DELETE_SELF | IN_MOVE_SELF | \
                  IN_CREATE | IN_DELETE | IN_MODIFY | IN_MOVED_FROM | IN_MOVED_TO)
#define SYMLINK_MASK (IN_DELETE_SELF | IN_MOVE_SELF)
#define FORMER_SYMLINK_MASK (IN_CLOSE_WRITE | IN_DELETE_SELF | IN_MOVE_SELF)

static int inotify_fd = -1;

static uint32_t mask_for_watch(WatchFile *wf, int actual_is_dir, int actual_is_symlink)
{
    if (wf->symlink_profile) {
        if (actual_is_symlink)
            return SYMLINK_MASK;
        if (actual_is_dir)
            return DIR_MASK & ~IN_ATTRIB;
        return FORMER_SYMLINK_MASK;
    }
    if (actual_is_dir)
        return DIR_MASK;
    (void)actual_is_symlink;
    return inotify_workaround ? FILE_MASK_WORKAROUND : FILE_MASK;
}

/* Register (or re-register) the watch for wf based on the path's current
 * state.  Returns 0 on success, 1 if the path does not exist (lstat failed),
 * 2 if inotify registration failed (errno preserved). */
static int try_register_watch(WatchFile *wf, int *out_errno)
{
    struct stat ls;
    if (lstat(wf->name, &ls) != 0) {
        *out_errno = errno;
        return 1;
    }
    struct stat fs;
    int have_fstat = (stat(wf->name, &fs) == 0);
    int actual_is_symlink = S_ISLNK(ls.st_mode);
    int actual_is_dir;
    if (wf->symlink_profile)
        actual_is_dir = have_fstat && S_ISDIR(fs.st_mode) && !actual_is_symlink ?
                        0 : (have_fstat && S_ISDIR(fs.st_mode) && actual_is_symlink ? 1 : 0);
    else
        actual_is_dir = have_fstat ? S_ISDIR(fs.st_mode) : S_ISDIR(ls.st_mode);
    /* For a symlink-profile directory target the link itself is not a dir;
     * a path that resolves to a directory is treated through the resolved
     * dir only when the file itself is not a link.  Simplify: if the path
     * itself is a link and profile is set, it is not a dir watch. */
    if (wf->symlink_profile && actual_is_symlink)
        actual_is_dir = 0;

    uint32_t mask = mask_for_watch(wf, actual_is_dir, actual_is_symlink);
    uint32_t flags = 0;
    if (wf->symlink_profile && actual_is_symlink)
        flags = IN_DONT_FOLLOW;
    int wd = inotify_add_watch(inotify_fd, wf->name, mask | flags);
    if (wd < 0) {
        *out_errno = errno;
        return 2;
    }
    int old_wd = wf->wd;
    wf->wd = wd;
    wf->watch_is_dir = actual_is_dir;
    wf->currently_symlink = actual_is_symlink;
    if (old_wd >= 0 && old_wd != wd)
        inotify_rm_watch(inotify_fd, old_wd);
    return 0;
}

static void register_watch_or_err(WatchFile *wf)
{
    int e = 0;
    int r = try_register_watch(wf, &e);
    if (r != 0) {
        errno = e;
        err(1, "failed to register VNODE event");
    }
}

/* Reopen a file after a DELETE/RENAME event.  Exits the process on fatal
 * errors, mirroring the observed messages. */
static void reopen_file(WatchFile *wf)
{
    int last_errno = ENOENT;
    for (int attempt = 0; attempt <= 10; attempt++) {
        if (attempt > 0) {
            if (sleep_ms_interruptible(100) < 0)
                check_immediate_exits();
            check_immediate_exits();
        }
        struct stat before;
        int have_before = (lstat(wf->name, &before) == 0);
        int e = 0;
        int r = try_register_watch(wf, &e);
        if (r == 0) {
            if (!wf->symlink_profile) {
                struct stat sb;
                if (stat_for_mode(wf->name, &sb) == 0)
                    wf->mode = sb.st_mode;
                else if (have_before)
                    wf->mode = before.st_mode;
            }
            return;
        }
        if (r == 2) {
            errno = e;
            err(1, "failed to register VNODE event");
        }
        last_errno = e;
    }
    errno = last_errno;
    err(1, "cannot open '%s'", wf->name);
}

static void reregister_dir_watch(WatchFile *wf)
{
    int e = 0;
    int old = wf->wd;
    wf->wd = -1; /* avoid removing a possibly-new wd */
    int r = try_register_watch(wf, &e);
    if (r != 0) {
        /* count_dir_entries() has already verified the directory exists;
         * a failure here is fatal in the same way as initial registration */
        if (r == 2) {
            errno = e;
            err(1, "failed to register VNODE event");
        }
        wf->wd = old;
    }
}

/* ---------- usage / argument parsing ---------- */

static void print_usage(int help)
{
    fprintf(stderr, "release: %s\n", release_str);
    fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
    if (help) {
        fprintf(stdout,
            "summary:\n"
            "    -a  Do not consolidate events\n"
            "    -c  Clear screen before execution\n"
            "    -d  Track files added or removed from directories\n"
            "    -n  Non-interactive mode\n"
            "    -p  Wait for first event\n"
            "    -r  Run as a background process, use signal to restart\n"
            "    -s  Evaluate using a shell\n"
            "    -x  Format exit status\n"
            "    -z  Exit after the utility completes\n"
            "docs:\n"
            "    man entr\n");
    } else {
        fprintf(stderr, "hint: use -h to display option summary\n");
    }
    exit(1);
}

static int parse_restart_signal(void)
{
    static const struct { const char *name; int sig; } table[] = {
        { "HUP", SIGHUP }, { "INT", SIGINT }, { "QUIT", SIGQUIT },
        { "TERM", SIGTERM }, { "USR1", SIGUSR1 }, { "USR2", SIGUSR2 },
    };
    const char *env = getenv("ENTR_RESTART_SIGNAL");
    if (!env)
        return SIGTERM;
    const char *name = env;
    if (strncmp(name, "SIG", 3) == 0)
        name += 3;
    /* The observed binary only matches the first three entries. */
    for (size_t i = 0; i < 3; i++) {
        if (strcmp(name, table[i].name) == 0)
            return table[i].sig;
    }
    errx(1, "unrecognized signal: %s <> (HUP, INT, QUIT, TERM, USR1, USR2)", name);
    return SIGTERM; /* not reached */
}

/* ---------- status (-x) machinery ---------- */

static const char status_script_content[] =
    "# http://eradman.com/entrproject/status-filters.html\n"
    "/^signal/ { print $3, \"terminated by signal\", $2; }\n"
    "/^exit/ { print $3, \"returned exit code\", $2; }\n";

static void resolve_status_script(void)
{
    const char *env = getenv("ENTR_STATUS_SCRIPT");
    if (env && env[0]) {
        status_script_path = xstrdup(env);
    } else {
        struct passwd *pw = getpwuid(getuid());
        const char *home = pw ? pw->pw_dir : "";
        size_t n = strlen(home) + strlen("/.entr/status.awk") + 1;
        status_script_path = xmalloc(n);
        snprintf(status_script_path, n, "%s/.entr/status.awk", home);
    }
    struct stat sb;
    if (stat(status_script_path, &sb) != 0) {
        status_script_need_create = 1;
        printf("entr: created '%s'\n", status_script_path);
    }
}

static void create_status_script(void)
{
    if (!status_script_need_create)
        return;
    char *copy = xstrdup(status_script_path);
    char *slash = strrchr(copy, '/');
    if (slash) {
        *slash = '\0';
        if (copy[0])
            mkdir(copy, 0750);
    }
    free(copy);
    int fd = open(status_script_path, O_WRONLY | O_CREAT | O_TRUNC, 0640);
    if (fd < 0)
        err(1, "open");
    const char *p = status_script_content;
    size_t left = strlen(p);
    while (left) {
        ssize_t w = write(fd, p, left);
        if (w < 0) {
            if (errno == EINTR)
                continue;
            break;
        }
        p += w;
        left -= (size_t)w;
    }
    close(fd);
}

static void start_status_process(void)
{
    int pipefd[2];
    if (pipe(pipefd) < 0)
        err(1, "pipe");
    pid_t pid = fork();
    if (pid < 0)
        err(1, "fork");
    if (pid == 0) {
        if (dup2(pipefd[0], STDIN_FILENO) < 0)
            _exit(1);
        close(pipefd[0]);
        close(pipefd[1]);
        char *args[7];
        int i = 0;
        args[i++] = (char *)"awk";
        args[i++] = (char *)"-F";
        args[i++] = (char *)"|";
        args[i++] = (char *)"-f";
        args[i++] = status_script_path;
        if (opt_x_count == 1)
            args[i++] = (char *)"-S";
        args[i] = NULL;
        execvp("awk", args);
        err(1, "could not exec /usr/bin/awk");
    }
    status_pid = pid;
    close(pipefd[0]);
    status_fd = pipefd[1];
}

static int open_max_value(void)
{
    FILE *f = fopen("/proc/sys/fs/inotify/max_user_watches", "r");
    if (f) {
        long v;
        if (fscanf(f, "%ld", &v) == 1) {
            fclose(f);
            return (int)v;
        }
        fclose(f);
    }
    long v = sysconf(_SC_OPEN_MAX);
    return v > 0 ? (int)v : 0;
}

/* ---------- events ---------- */

typedef struct {
    WatchFile *file;
    unsigned fflags;
    int index;          /* index within the batch */
    int keep_trace;
    int mode_changed;
    int dir_altered;
} FileEvent;

typedef struct {
    FileEvent *v;
    size_t len, cap;
} EventList;

static void events_push(EventList *l, FileEvent e)
{
    if (l->len == l->cap) {
        l->cap = l->cap ? l->cap * 2 : 16;
        l->v = xrealloc(l->v, l->cap * sizeof(*l->v));
    }
    l->v[l->len++] = e;
}

static WatchFile *find_file_by_wd(int wd)
{
    for (size_t i = 0; i < files_len; i++)
        if (files[i].wd == wd)
            return &files[i];
    return NULL;
}

static unsigned map_inotify_event(WatchFile *wf, uint32_t mask)
{
    unsigned ff = 0;
    if (wf->watch_is_dir) {
        if (mask & IN_ATTRIB) ff |= NOTE_ATTRIB;
        if (mask & (IN_CLOSE_WRITE | IN_MODIFY | IN_CREATE | IN_DELETE)) ff |= NOTE_WRITE;
        if (mask & (IN_MOVED_FROM | IN_MOVED_TO | IN_MOVE_SELF)) ff |= NOTE_RENAME;
        if (mask & IN_DELETE_SELF) ff |= NOTE_DELETE;
        return ff;
    }
    if (wf->symlink_profile && wf->currently_symlink) {
        if (mask & IN_DELETE_SELF) ff |= NOTE_DELETE;
        if (mask & IN_MOVE_SELF) ff |= NOTE_RENAME;
        return ff;
    }
    if (mask & IN_CLOSE_WRITE) ff |= NOTE_WRITE;
    if (inotify_workaround && (mask & IN_MODIFY)) ff |= NOTE_WRITE;
    if (mask & IN_ATTRIB) ff |= NOTE_ATTRIB;
    if (mask & IN_DELETE_SELF) ff |= NOTE_DELETE;
    if (mask & IN_MOVE_SELF) ff |= NOTE_RENAME;
    return ff;
}

/* Read and convert all currently available inotify records, merging
 * consecutive records that belong to the same watched file. */
static void read_inotify_events(EventList *out)
{
    char buf[64 * 1024];
    for (;;) {
        ssize_t n = read(inotify_fd, buf, sizeof(buf));
        if (n < 0) {
            if (errno == EINTR) {
                if (seen_int || seen_hup)
                    return;
                continue;
            }
            return; /* EAGAIN: drained */
        }
        if (n == 0)
            return;
        size_t off = 0;
        while (off + sizeof(struct inotify_event) <= (size_t)n) {
            struct inotify_event *ie = (struct inotify_event *)(buf + off);
            off += sizeof(struct inotify_event) + ie->len;
            if (ie->mask & IN_IGNORED) {
                WatchFile *f = find_file_by_wd(ie->wd);
                if (f && f->wd == ie->wd && out->len == 0) {
                    /* Defer clearing the wd until batch processing has had
                     * a chance to reopen; it is simply stale now. */
                }
                continue;
            }
            WatchFile *f = find_file_by_wd(ie->wd);
            if (!f)
                continue;
            unsigned ff = map_inotify_event(f, ie->mask);
            if (ff == 0)
                continue;
            if (out->len > 0) {
                FileEvent *last = &out->v[out->len - 1];
                if (last->file == f) {
                    last->fflags |= ff;
                    continue;
                }
            }
            FileEvent e;
            memset(&e, 0, sizeof(e));
            e.file = f;
            e.fflags = ff;
            e.index = (int)out->len;
            e.keep_trace = 1;
            events_push(out, e);
        }
    }
}

enum WaitKind { WK_TIMEOUT, WK_SIGNAL, WK_TTY, WK_BATCH };

/* Wait for the next thing to happen.
 *  initial_timeout_ms < 0 waits forever.
 *  On WK_BATCH, out contains converted file events.
 *  On WK_TTY, *tty_char contains one byte read from the TTY. */
static enum WaitKind wait_for_events(int initial_timeout_ms, EventList *out, int *tty_char)
{
    out->len = 0;
    /* Build poll set */
    struct pollfd pfds[3];
    int nfds = 0;
    int idx_inotify = -1, idx_tty = -1, idx_sig = -1;
    /* inotify */
    idx_inotify = nfds;
    pfds[nfds].fd = inotify_fd;
    pfds[nfds].events = POLLIN;
    pfds[nfds].revents = 0;
    nfds++;
    if (tty_fd >= 0) {
        idx_tty = nfds;
        pfds[nfds].fd = tty_fd;
        pfds[nfds].events = POLLIN;
        pfds[nfds].revents = 0;
        nfds++;
    }
    if (sig_pipe[0] >= 0) {
        idx_sig = nfds;
        pfds[nfds].fd = sig_pipe[0];
        pfds[nfds].events = POLLIN;
        pfds[nfds].revents = 0;
        nfds++;
    }

    int timeout = initial_timeout_ms;
    for (;;) {
        int r = poll(pfds, nfds, timeout);
        if (r < 0) {
            if (errno == EINTR)
                return WK_SIGNAL;
            return WK_TIMEOUT;
        }
        if (r == 0)
            return WK_TIMEOUT;
        break;
    }

    int sig_ready = (idx_sig >= 0 && (pfds[idx_sig].revents & POLLIN));
    int tty_ready = (idx_tty >= 0 && (pfds[idx_tty].revents & (POLLIN | POLLHUP)));
    int ino_ready = (pfds[idx_inotify].revents & (POLLIN));

    if (sig_ready) {
        /* drain the signal pipe */
        char tmp[64];
        ssize_t ignored = read(sig_pipe[0], tmp, sizeof(tmp));
        (void)ignored;
        if (!ino_ready && !tty_ready)
            return WK_SIGNAL;
        /* Prefer handling a terminating signal before a batch */
        if (seen_int || seen_hup || seen_term)
            return WK_SIGNAL;
        if (!ino_ready && !tty_ready)
            return WK_SIGNAL;
    }

    if (tty_ready && !ino_ready) {
        unsigned char c;
        ssize_t n = read(tty_fd, &c, 1);
        if (n == 1) {
            *tty_char = c;
            return WK_TTY;
        }
        /* EOF/error on tty: stop offering it */
        tty_fd = -1;
        return WK_TIMEOUT;
    }

    if (ino_ready) {
        /* collect a batch: keep reading until 50 ms of quiet */
        read_inotify_events(out);
        int64_t deadline = now_ms() + 50;
        for (;;) {
            int64_t remain = deadline - now_ms();
            if (remain <= 0)
                break;
            struct pollfd p2[3];
            int n2 = 0;
            p2[n2].fd = inotify_fd; p2[n2].events = POLLIN; p2[n2].revents = 0; n2++;
            int sigi = -1;
            if (sig_pipe[0] >= 0) {
                sigi = n2;
                p2[n2].fd = sig_pipe[0]; p2[n2].events = POLLIN; p2[n2].revents = 0; n2++;
            }
            int rr = poll(p2, n2, (int)remain);
            if (rr < 0) {
                if (errno == EINTR)
                    break;
                break;
            }
            if (rr == 0)
                break;
            if (sigi >= 0 && (p2[sigi].revents & POLLIN)) {
                char tmp[64];
                ssize_t ignored = read(sig_pipe[0], tmp, sizeof(tmp));
                (void)ignored;
                if (seen_int || seen_hup || seen_term)
                    break;
                /* a child changed state; let the caller notice, but keep
                 * collecting file events briefly */
            }
            if (p2[0].revents & POLLIN) {
                read_inotify_events(out);
                deadline = now_ms() + 50;
            }
        }
        /* assign indices (merging may have changed counts only via push) */
        for (size_t i = 0; i < out->len; i++)
            out->v[i].index = (int)i;
        return WK_BATCH;
    }

    if (tty_ready) {
        unsigned char c;
        ssize_t n = read(tty_fd, &c, 1);
        if (n == 1) {
            *tty_char = c;
            return WK_TTY;
        }
        tty_fd = -1;
        return WK_TIMEOUT;
    }
    if (sig_ready)
        return WK_SIGNAL;
    return WK_TIMEOUT;
}

/* ---------- utility execution ---------- */

static pid_t utility_child_pid;   /* non-r child being waited, or r child */
static int r_child_running;
static pid_t r_child_pid;
static int r_child_last_status;
static int r_child_has_status;
static int child_exited_flag;     /* set when r child reaped outside wait */

/* forward */
static int convert_status(int raw)
{
    if (WIFEXITED(raw))
        return WEXITSTATUS(raw);
    if (WIFSIGNALED(raw))
        return 128 + WTERMSIG(raw);
    return 0;
}

static char *last_status_name;   /* basename used in -x status lines */

static void compute_status_name(const char *shell_path)
{
    free(last_status_name);
    if (opt_s)
        last_status_name = status_basename(shell_path ? shell_path : "");
    else
        last_status_name = status_basename(utility_args[0]);
}

static void write_status_line(int raw)
{
    if (!opt_x_count || status_fd < 0 || status_dead)
        return;
    const char *name = last_status_name ? last_status_name : "";
    if (WIFEXITED(raw)) {
        int ignored = dprintf(status_fd, "exit|%d|%s\n", WEXITSTATUS(raw), name);
        (void)ignored;
    } else if (WIFSIGNALED(raw)) {
        int ignored = dprintf(status_fd, "signal|%d|%s\n", WTERMSIG(raw), name);
        (void)ignored;
    }
}

static void prepare_exec_argv(WatchFile *trig, char ***out_argv, const char **out_shell)
{
    const char *shell_path = NULL;
    char **argv;
    if (opt_s) {
        shell_path = getenv("SHELL");
        if (!shell_path)
            shell_path = "/bin/sh";
        argv = xmalloc(5 * sizeof(char *));
        argv[0] = (char *)shell_path;
        argv[1] = (char *)"-c";
        argv[2] = (char *)shell_command;
        argv[3] = trig ? (char *)trig->name : (char *)"";
        argv[4] = NULL;
    } else {
        argv = xmalloc(((size_t)utility_argc + 1) * sizeof(char *));
        int replaced = 0;
        for (int i = 0; i < utility_argc; i++) {
            const char *a = utility_args[i];
            if (!replaced && strcmp(a, "/_") == 0) {
                a = trig ? trig->name : a;
                replaced = 1;
            }
            argv[i] = (char *)a;
        }
        argv[utility_argc] = NULL;
    }
    *out_argv = argv;
    *out_shell = shell_path;
}

/* Wait for a specific child.  Sets *terminate_after if SIGINT/SIGHUP was
 * received while waiting.  Detects status-process termination. */
static int wait_for_child(pid_t pid, int *terminate_after)
{
    int raw = 0;
    *terminate_after = 0;
    for (;;) {
        pid_t r = waitpid(pid, &raw, 0);
        if (r == pid)
            break;
        if (r < 0 && errno == EINTR) {
            if (check_status_dead()) {
                /* keep waiting for the utility */
            }
            if (seen_int || seen_hup) {
                *terminate_after = 1;
                seen_int = 0;
                seen_hup = 0;
            }
            seen_chld = 0;
            continue;
        }
        if (r < 0) {
            raw = 0;
            break;
        }
    }
    seen_chld = 0;
    return raw;
}

/* Print clear-screen sequence if requested */
static void do_clear_screen(void)
{
    if (opt_c_count == 1)
        fputs("\033[2J\033[H", stdout);
    else if (opt_c_count >= 2)
        fputs("\033[2J\033[3J\033[H", stdout);
}

/* Run the utility synchronously (non -r).  Returns raw wait status. */
static int run_utility_nonr(int *terminate_after)
{
    WatchFile *trig = trigger_file;
    char **exec_argv;
    const char *shell_path;
    prepare_exec_argv(trig, &exec_argv, &shell_path);
    compute_status_name(shell_path);

    do_clear_screen();
    fflush(stdout);
    if (tty_active)
        tcsetattr(tty_fd, TCSANOW, &tty_orig);

    pid_t pid = fork();
    if (pid < 0)
        err(1, "fork");
    if (pid == 0) {
        /* child */
        if (sig_pipe[1] >= 0)
            close(sig_pipe[1]);
        if (tty_active && tty_fd >= 0) {
            if (dup2(tty_fd, STDIN_FILENO) < 0) {
                /* fall through */
            }
            if (tty_fd > STDERR_FILENO)
                close(tty_fd);
        }
        execvp(exec_argv[0], exec_argv);
        err(1, "exec %s", exec_argv[0]);
    }
    utility_child_pid = pid;
    int raw = wait_for_child(pid, terminate_after);
    utility_child_pid = 0;
    if (tty_active)
        tcsetattr(tty_fd, TCSANOW, &tty_new);
    if (!*terminate_after && !status_dead)
        write_status_line(raw);
    free(exec_argv);
    return raw;
}

/* terminate the -r child process group and wait for it */
static void terminate_r_child(void)
{
    if (!r_child_running || r_child_pid <= 0)
        return;
    pid_t pid = r_child_pid;
    kill(-pid, restart_signal);
    int dummy_terminate = 0;
    int raw = 0;
    /* wait specifically for this child */
    for (;;) {
        pid_t r = waitpid(pid, &raw, 0);
        if (r == pid)
            break;
        if (r < 0 && errno == EINTR) {
            seen_chld = 0;
            continue;
        }
        break;
    }
    (void)dummy_terminate;
    r_child_running = 0;
    r_child_pid = 0;
    seen_chld = 0;
}

static void start_r_child(void)
{
    WatchFile *trig = trigger_file;
    char **exec_argv;
    const char *shell_path;
    prepare_exec_argv(trig, &exec_argv, &shell_path);
    compute_status_name(shell_path);

    do_clear_screen();
    fflush(stdout);

    pid_t pid = fork();
    if (pid < 0)
        err(1, "fork");
    if (pid == 0) {
        setpgid(0, 0);
        int fd = open("/dev/null", O_RDONLY);
        if (fd >= 0) {
            dup2(fd, STDIN_FILENO);
            if (fd > STDERR_FILENO)
                close(fd);
        }
        if (sig_pipe[1] >= 0)
            close(sig_pipe[1]);
        if (tty_fd > STDERR_FILENO)
            close(tty_fd);
        execvp(exec_argv[0], exec_argv);
        err(1, "exec %s", exec_argv[0]);
    }
    setpgid(pid, pid);
    r_child_pid = pid;
    r_child_running = 1;
    r_child_has_status = 0;
    free(exec_argv);
}

/* Check whether the -r child has exited; reap it if so */
static int check_r_child_exit(void)
{
    if (!opt_r || !r_child_running || r_child_pid <= 0)
        return 0;
    int raw;
    pid_t r = waitpid(r_child_pid, &raw, WNOHANG);
    if (r == r_child_pid) {
        r_child_running = 0;
        r_child_pid = 0;
        r_child_last_status = raw;
        r_child_has_status = 1;
        child_exited_flag = 1;
        return 1;
    }
    if (r < 0 && errno == ECHILD) {
        r_child_running = 0;
        r_child_pid = 0;
        return 1;
    }
    return 0;
}

/* ---------- event batch processing ---------- */

static int batch_has_reopen;   /* a delete/rename reopen happened */

/* Collate phase: handle directory counts and deleted/renamed files.
 * No trace output happens here.  Sets per-event keep_trace / dir_altered
 * and updates stored modes for ATTRIB events. */
static void collate_events(EventList *batch, int *out_dir_altered)
{
    *out_dir_altered = 0;
    batch_has_reopen = 0;
    for (size_t i = 0; i < batch->len; i++) {
        check_immediate_exits();
        FileEvent *e = &batch->v[i];
        WatchFile *f = e->file;
        e->keep_trace = 1;
        e->mode_changed = 0;
        e->dir_altered = 0;
        if (f->is_dir) {
            int cnt = count_dir_entries(f->name);
            if (cnt != f->dir_count) {
                /* confirm after a short settling delay */
                if (sleep_ms_interruptible(500) < 0)
                    check_immediate_exits();
                check_immediate_exits();
                int cnt2 = count_dir_entries(f->name);
                if (cnt2 != f->dir_count) {
                    e->dir_altered = 1;
                    *out_dir_altered = 1;
                } else {
                    e->keep_trace = 0;
                }
            } else {
                e->keep_trace = 0;
            }
            if (e->fflags & (NOTE_DELETE | NOTE_RENAME)) {
                reregister_dir_watch(f);
            }
            /* refresh stored mode for the trace in case it changed */
            if (e->fflags & NOTE_ATTRIB) {
                struct stat sb;
                if (stat_for_mode(f->name, &sb) == 0)
                    f->mode = sb.st_mode;
            }
        } else {
            if (f->symlink_profile && (e->fflags & (NOTE_DELETE | NOTE_RENAME)))
                e->keep_trace = 0;
            if (e->fflags & (NOTE_DELETE | NOTE_RENAME | NOTE_REVOKE)) {
                reopen_file(f);
                batch_has_reopen = 1;
            }
            if (!f->symlink_profile && (e->fflags & NOTE_ATTRIB)) {
                struct stat sb;
                if (stat_for_mode(f->name, &sb) == 0) {
                    e->mode_changed = (sb.st_mode != f->mode);
                    f->mode = sb.st_mode;
                }
            }
        }
    }
}

static void print_traces(EventList *batch)
{
    if (!getenv("EV_TRACE"))
        return;
    int total = (int)batch->len;
    for (size_t i = 0; i < batch->len; i++) {
        FileEvent *e = &batch->v[i];
        if (!e->keep_trace)
            continue;
        fprintf(stderr, "%d/%d: fflags: 0x%x %c %o %s\n",
                e->index, total, e->fflags,
                e->file->is_dir ? 'd' : 'r',
                (unsigned)e->file->mode, e->file->name);
    }
}

/* Decide whether this batch should run the utility.  If so, *candidate is
 * the file that first qualified (or NULL to keep the current trigger). */
static int batch_decide(EventList *batch, WatchFile **candidate)
{
    int should_run = 0;
    *candidate = NULL;
    for (size_t i = 0; i < batch->len; i++) {
        FileEvent *e = &batch->v[i];
        WatchFile *f = e->file;
        if (f->is_dir) {
            if (e->dir_altered)
                should_run = 1;
            continue;
        }
        int qualifies = 0;
        if (e->fflags & (NOTE_WRITE | NOTE_EXTEND))
            qualifies = 1;
        else if (e->fflags & (NOTE_DELETE | NOTE_RENAME | NOTE_REVOKE))
            qualifies = 1;
        else if (e->fflags & NOTE_ATTRIB) {
            if (e->mode_changed)
                qualifies = 1;
        }
        if (qualifies) {
            if (!*candidate)
                *candidate = f;
            should_run = 1;
        }
    }
    return should_run;
}

/* Consolidation after a run (when -a is not set).  Drains one batch of
 * pending events, reopening deleted files.  Returns 1 if a 'q' key was
 * consumed from the TTY while draining. */
static int clear_pending_events(void)
{
    EventList batch;
    memset(&batch, 0, sizeof(batch));
    int tty_char = 0;
    enum WaitKind k = wait_for_events(50, &batch, &tty_char);
    if (k == WK_TTY) {
        free(batch.v);
        return tty_char == 'q' ? 1 : 0;
    }
    if (k == WK_SIGNAL) {
        check_r_child_exit();
        free(batch.v);
        return 0;
    }
    if (k == WK_TIMEOUT) {
        free(batch.v);
        return 0;
    }
    /* WK_BATCH: discard, but reopen deleted/renamed files */
    for (size_t i = 0; i < batch.len; i++) {
        FileEvent *e = &batch.v[i];
        WatchFile *f = e->file;
        if (f->is_dir) {
            if (e->fflags & (NOTE_DELETE | NOTE_RENAME))
                reregister_dir_watch(f);
            continue;
        }
        if (e->fflags & (NOTE_DELETE | NOTE_RENAME | NOTE_REVOKE))
            reopen_file(f);
    }
    free(batch.v);
    return 0;
}

/* ---------- main ---------- */

int main(int argc, char **argv)
{
    /* -h as the very first argument */
    if (argc > 1 && strcmp(argv[1], "-h") == 0)
        print_usage(1);

    /* option parsing: stop at the first non-option */
    int idx = 1;
    while (idx < argc) {
        char *arg = argv[idx];
        if (arg[0] != '-' || arg[1] == '\0')
            break;
        if (strcmp(arg, "--") == 0) {
            idx++;
            break;
        }
        int bad = 0;
        for (int j = 1; arg[j] != '\0'; j++) {
            switch (arg[j]) {
            case 'a': opt_a = 1; break;
            case 'c': opt_c_count++; break;
            case 'd': opt_d_count++; break;
            case 'n': opt_n = 1; break;
            case 'p': opt_p = 1; break;
            case 'r': opt_r = 1; break;
            case 's': opt_s = 1; break;
            case 'x': opt_x_count++; break;
            case 'z': opt_z = 1; break;
            default:
                fprintf(stderr, "%s: invalid option -- '%c'\n", argv[0], arg[j]);
                bad = 1;
                break;
            }
            if (bad)
                break;
        }
        if (bad) {
            fprintf(stderr, "release: %s\n", release_str);
            fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
            fprintf(stderr, "hint: use -h to display option summary\n");
            return 1;
        }
        idx++;
    }

    if (idx >= argc)
        print_usage(0);

    utility_args = argv + idx;
    utility_argc = argc - idx;

    if (opt_r && opt_x_count)
        errx(1, "-r and -x may not be combined");
    if (opt_s && utility_argc != 1)
        errx(1, "-s requires commands to be formatted as a single argument");
    if (opt_s)
        shell_command = utility_args[0];

    restart_signal = parse_restart_signal();

    follow_symlink = getenv("ENTR_FOLLOW_SYMLINK") != NULL;
    inotify_workaround = getenv("ENTR_INOTIFY_WORKAROUND") != NULL;

    if (getenv("PAGER") == NULL)
        setenv("PAGER", "/bin/cat", 1);

    /* status script path / creation announcement */
    if (opt_x_count)
        resolve_status_script();

    /* signal self-pipe */
    if (pipe(sig_pipe) < 0)
        err(1, "pipe");
    for (int i = 0; i < 2; i++) {
        int fl = fcntl(sig_pipe[i], F_GETFL, 0);
        fcntl(sig_pipe[i], F_SETFL, fl | O_NONBLOCK);
    }
    install_signal_handlers();

    /* event-system initialisation messages */
    inotify_fd = inotify_init1(IN_NONBLOCK | IN_CLOEXEC);
    if (inotify_fd < 0)
        err(1, "inotify_init");
    if (getenv("EV_TRACE"))
        fprintf(stderr, "open_max: %d\n", open_max_value());
    if (inotify_workaround)
        warnx("broken inotify workaround enabled");

    if (opt_x_count) {
        create_status_script();
        if (isatty(STDIN_FILENO))
            print_usage(0);
        start_status_process();
    } else {
        if (isatty(STDIN_FILENO))
            print_usage(0);
    }

    /* ---- read file list from stdin ---- */
    char **names = NULL;
    size_t names_len = 0, names_cap = 0;
    {
        char buf[4096];
        for (;;) {
            check_immediate_exits();
            if (fgets(buf, sizeof(buf), stdin) == NULL) {
                if (feof(stdin))
                    break;
                if (ferror(stdin) && errno == EINTR) {
                    clearerr(stdin);
                    check_immediate_exits();
                    continue;
                }
                break;
            }
            char *nl = strchr(buf, '\n');
            if (nl)
                *nl = '\0';
            if (buf[0] == '\0')
                continue;
            if (names_len == names_cap) {
                names_cap = names_cap ? names_cap * 2 : 32;
                names = xrealloc(names, names_cap * sizeof(char *));
            }
            names[names_len++] = xstrdup(buf);
        }
    }
    check_immediate_exits();

    /* ---- classify files ---- */
    size_t accepted_inputs = 0;
    for (size_t ni = 0; ni < names_len; ni++) {
        const char *name = names[ni];
        struct stat sb;
        int r = follow_symlink ? stat(name, &sb) : lstat(name, &sb);
        if (r != 0) {
            warnx("unable to stat '%s'", name);
            continue;
        }
        int is_dir, is_link = 0;
        if (S_ISREG(sb.st_mode)) {
            is_dir = 0;
        } else if (S_ISDIR(sb.st_mode)) {
            is_dir = 1;
        } else if (S_ISLNK(sb.st_mode)) {
            is_dir = 0;
            is_link = 1;
        } else {
            continue;
        }
        WatchFile wf;
        memset(&wf, 0, sizeof(wf));
        wf.name = xstrdup(name);
        wf.mode = sb.st_mode;
        wf.is_dir = is_dir;
        wf.symlink_profile = (is_link && !follow_symlink) ? 1 : 0;
        wf.currently_symlink = is_link ? 1 : 0;
        wf.wd = -1;
        if (is_dir)
            wf.dir_count = count_dir_entries(name);
        files_append(wf);
        accepted_inputs++;

        if (opt_d_count > 0 && !is_dir) {
            char *parent = parent_dirname(name);
            /* deduplicate directory entries */
            int found = 0;
            for (size_t k = 0; k < files_len; k++) {
                if (files[k].is_dir && strcmp(files[k].name, parent) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                WatchFile pf;
                memset(&pf, 0, sizeof(pf));
                pf.name = parent;
                pf.is_dir = 1;
                pf.is_parent = 1;
                pf.wd = -1;
                struct stat psb;
                if (stat_for_mode(parent, &psb) == 0)
                    pf.mode = psb.st_mode;
                else
                    pf.mode = (mode_t)040755;
                pf.dir_count = count_dir_entries(parent);
                files_append(pf);
            } else {
                free(parent);
            }
        }
    }

    if (accepted_inputs == 0) {
        warnx("No regular files to watch");
        return 1;
    }
    trigger_file = &files[0];

    /* ---- register watches ---- */
    for (size_t i = 0; i < files_len; i++)
        register_watch_or_err(&files[i]);

    /* ---- TTY ---- */
    if (!opt_n) {
        tty_fd = open("/dev/tty", O_RDWR);
        if (tty_fd < 0 || tcgetattr(tty_fd, &tty_orig) < 0) {
            errx(1, "unable to get terminal attributes, use '-n' to run non-interactively");
        }
        tty_new = tty_orig;
        tty_new.c_lflag &= ~(ICANON | ECHO);
        tcsetattr(tty_fd, TCSANOW, &tty_new);
        tty_active = 1;
        atexit(restore_tty_atexit);
    }

    /* ================= run / watch loop ================= */

    if (!opt_r) {
        /* non-reload mode */
        if (!opt_p) {
            int terminate_after = 0;
            int raw = run_utility_nonr(&terminate_after);
            if (terminate_after || seen_int || seen_hup)
                return 0;
            if (status_dead)
                return 0;
            check_status_dead();
            if (status_dead)
                return 0;
            if (opt_z)
                return convert_status(raw);
            if (!opt_a)
                if (clear_pending_events())
                    return 0;
        }
        for (;;) {
            EventList batch;
            memset(&batch, 0, sizeof(batch));
            int tty_char = 0;
            enum WaitKind k = wait_for_events(-1, &batch, &tty_char);
            if (k == WK_SIGNAL) {
                check_immediate_exits();
                free(batch.v);
                continue;
            }
            if (k == WK_TIMEOUT) {
                free(batch.v);
                continue;
            }
            if (k == WK_TTY) {
                free(batch.v);
                if (tty_char == 'q')
                    return 0;
                if (tty_char == ' ') {
                    int terminate_after = 0;
                    int raw = run_utility_nonr(&terminate_after);
                    if (terminate_after || seen_int || seen_hup)
                        return 0;
                    if (status_dead)
                        return 0;
                    if (opt_z)
                        return convert_status(raw);
                    if (!opt_a)
                        if (clear_pending_events())
                            return 0;
                }
                continue;
            }
            /* WK_BATCH */
            check_immediate_exits();
            int dir_altered = 0;
            collate_events(&batch, &dir_altered);
            if (seen_int || seen_hup)
                return 0;
            if (check_status_dead())
                return 0;
            print_traces(&batch);
            WatchFile *candidate = NULL;
            int should_run = batch_decide(&batch, &candidate);
            if (should_run) {
                if (candidate)
                    trigger_file = candidate;
                if (batch_has_reopen)
                    if (sleep_ms_interruptible(50) < 0)
                        check_immediate_exits();
                int terminate_after = 0;
                int raw = run_utility_nonr(&terminate_after);
                free(batch.v);
                if (terminate_after || seen_int || seen_hup)
                    return 0;
                if (status_dead)
                    return 0;
                if (opt_z)
                    return convert_status(raw);
                if (dir_altered) {
                    warnx("directory altered");
                    return 2;
                }
                if (!opt_a)
                    if (clear_pending_events())
                        return 0;
            } else {
                free(batch.v);
            }
        }
    } else {
        /* reload mode */
        if (!opt_p)
            start_r_child();
        for (;;) {
            EventList batch;
            memset(&batch, 0, sizeof(batch));
            int tty_char = 0;
            enum WaitKind k = wait_for_events(-1, &batch, &tty_char);
            if (k == WK_SIGNAL) {
                /* child exit? */
                if (check_r_child_exit()) {
                    if (seen_int || seen_hup) {
                        return 0;
                    }
                    if (opt_r && seen_term)
                        exit_by_term_signal();
                    if (opt_z && r_child_has_status)
                        return convert_status(r_child_last_status);
                    free(batch.v);
                    continue;
                }
                if (seen_int || seen_hup) {
                    if (r_child_running)
                        terminate_r_child();
                    return 0;
                }
                if (seen_term) {
                    if (r_child_running)
                        terminate_r_child();
                    exit_by_term_signal();
                }
                free(batch.v);
                continue;
            }
            if (k == WK_TIMEOUT) {
                free(batch.v);
                continue;
            }
            if (k == WK_TTY) {
                free(batch.v);
                if (tty_char == 'q') {
                    if (r_child_running)
                        terminate_r_child();
                    return 0;
                }
                if (tty_char == ' ') {
                    if (r_child_running)
                        terminate_r_child();
                    if (seen_int || seen_hup)
                        return 0;
                    if (seen_term)
                        exit_by_term_signal();
                    start_r_child();
                    if (seen_int || seen_hup) {
                        if (r_child_running)
                            terminate_r_child();
                        return 0;
                    }
                    if (!opt_a) {
                        if (clear_pending_events()) {
                            if (r_child_running)
                                terminate_r_child();
                            return 0;
                        }
                        if (check_r_child_exit() && opt_z && r_child_has_status)
                            return convert_status(r_child_last_status);
                    }
                }
                continue;
            }
            /* WK_BATCH */
            if (seen_int || seen_hup) {
                if (r_child_running)
                    terminate_r_child();
                return 0;
            }
            if (seen_term) {
                if (r_child_running)
                    terminate_r_child();
                exit_by_term_signal();
            }
            /* if the child exited on its own and -z is set, leave now,
             * unless this batch wants a restart (handled below when the
             * child exit was noticed first) */
            int child_just_exited = check_r_child_exit();
            if (child_just_exited && opt_z && r_child_has_status) {
                /* A file event in the same batch loses to the completed
                 * utility when -z is set. */
                return convert_status(r_child_last_status);
            }
            int dir_altered = 0;
            collate_events(&batch, &dir_altered);
            if (seen_int || seen_hup) {
                if (r_child_running)
                    terminate_r_child();
                return 0;
            }
            print_traces(&batch);
            WatchFile *candidate = NULL;
            int should_run = batch_decide(&batch, &candidate);
            free(batch.v);
            if (should_run) {
                if (candidate)
                    trigger_file = candidate;
                if (batch_has_reopen)
                    if (sleep_ms_interruptible(50) < 0) {
                        if (r_child_running)
                            terminate_r_child();
                        check_immediate_exits();
                        return 0;
                    }
                if (r_child_running)
                    terminate_r_child();
                if (seen_int || seen_hup)
                    return 0;
                if (seen_term)
                    exit_by_term_signal();
                if (dir_altered) {
                    warnx("directory altered");
                    return 2;
                }
                start_r_child();
                if (seen_int || seen_hup) {
                    if (r_child_running)
                        terminate_r_child();
                    return 0;
                }
                if (!opt_a) {
                    if (clear_pending_events()) {
                        if (r_child_running)
                            terminate_r_child();
                        return 0;
                    }
                    if (check_r_child_exit() && opt_z && r_child_has_status)
                        return convert_status(r_child_last_status);
                    if (seen_int || seen_hup) {
                        if (r_child_running)
                            terminate_r_child();
                        return 0;
                    }
                }
            } else if (dir_altered) {
                /* dir_altered implies should_run, kept for safety */
                if (r_child_running)
                    terminate_r_child();
                warnx("directory altered");
                return 2;
            }
        }
    }
    return 0;
}
