                if (check_r_child_exit()) {
                    if (seen_int || seen_hup) {
                        return 0;
                    }
                    if (opt_r && seen_term)
                        exit_by_term_signal();
                    if (opt_z && r_child_has_status)
                        return convert_status(r_child_last_status);
                    free(batch.v);
                    continue;
                }
                if (seen_int || seen_hup) {
                    if (r_child_running)
                        terminate_r_child();
                    return 0;
                }
                if (seen_term) {
                    if (r_child_running)
                        terminate_r_child();
                    exit_by_term_signal();
                }
                free(batch.v);
                continue;
            }
            if (k == WK_TIMEOUT) {
                free(batch.v);
                continue;
            }
            if (k == WK_TTY) {
                free(batch.v);
                if (tty_char == 'q') {
                    if (r_child_running)
                        terminate_r_child();
                    return 0;
                }
                if (tty_char == ' ') {
                    if (r_child_running)
                        terminate_r_child();
                    if (seen_int || seen_hup)
                        return 0;
                    if (seen_term)
                        exit_by_term_signal();
                    start_r_child();
                    if (seen_int || seen_hup) {
                        if (r_child_running)
                            terminate_r_child();
                        return 0;
                    }
                    if (!opt_a) {
                        if (clear_pending_events()) {
                            if (r_child_running)
                                terminate_r_child();
                            return 0;
                        }
                        if (check_r_child_exit() && opt_z && r_child_has_status)
                            return convert_status(r_child_last_status);
                    }
                }
                continue;
            }
            /* WK_BATCH */
            if (seen_int || seen_hup) {
                if (r_child_running)
                    terminate_r_child();
                return 0;
            }
            if (seen_term) {
                if (r_child_running)
                    terminate_r_child();
                exit_by_term_signal();
            }
            /* if the child exited on its own and -z is set, leave now,
             * unless this batch wants a restart (handled below when the
             * child exit was noticed first) */
            int child_just_exited = check_r_child_exit();
            if (child_just_exited && opt_z && r_child_has_status) {
                /* A file event in the same batch loses to the completed
                 * utility when -z is set. */
                return convert_status(r_child_last_status);
            }
            int dir_altered = 0;
            collate_events(&batch, &dir_altered);
            if (seen_int || seen_hup) {
                if (r_child_running)
                    terminate_r_child();
                return 0;
            }
            print_traces(&batch);
            WatchFile *candidate = NULL;
            int should_run = batch_decide(&batch, &candidate);
            free(batch.v);
            if (should_run) {
                if (candidate)
                    trigger_file = candidate;
                if (batch_has_reopen)
                    if (sleep_ms_interruptible(50) < 0) {
                        if (r_child_running)
                            terminate_r_child();
                        check_immediate_exits();
                        return 0;
                    }
                if (r_child_running)
                    terminate_r_child();
                if (seen_int || seen_hup)
                    return 0;
                if (seen_term)
                    exit_by_term_signal();
                if (dir_altered) {
                    warnx("directory altered");
                    return 2;
                }
                start_r_child();
                if (seen_int || seen_hup) {
                    if (r_child_running)
                        terminate_r_child();
                    return 0;
                }
                if (!opt_a) {
                    if (clear_pending_events()) {
                        if (r_child_running)
                            terminate_r_child();
                        return 0;
                    }
                    if (check_r_child_exit() && opt_z && r_child_has_status)
                        return convert_status(r_child_last_status);
                    if (seen_int || seen_hup) {
                        if (r_child_running)
                            terminate_r_child();
                        return 0;
                    }
                }
            } else if (dir_altered) {
                /* dir_altered implies should_run, kept for safety */
                if (r_child_running)
                    terminate_r_child();
                warnx("directory altered");
                return 2;
            }
        }
    }
    return 0;
}
